// What every page shares: the client and its commands, the navigation between the pages, a banner for
// a server whose model has moved on, and the few helpers that write a table. The model is generated by
// the Vite plugin; /api is forwarded to the server.

import { createCommands, createScry, httpTransport } from "scry-client";
import { schema, type Commands, type Sources } from "./scry.generated.ts";
import "./style.css";

// A path, not a URL: the page asks its own origin, and the dev server forwards /api to the server.
// begin-snippet: typescriptWebSetup
export const scry = createScry<Sources>(schema, {
  transport: httpTransport({ endpoint: "/api/query" }),
  onSchemaStale: offerReload
});
export const commands = createCommands<Commands>(scry);
// end-snippet

// Told once, the first time a response shows the server is on another model than the one this page
// was built from. The queries still answer, so the page offers a reload rather than taking one: it
// fetches the page built against the model the server now has.
// begin-snippet: typescriptWebStale
function offerReload(): void {
  const banner = document.createElement("div");
  banner.id = "stale";
  banner.className = "stale";
  banner.setAttribute("role", "alert");
  banner.textContent = "The server has been updated since this page was built. ";
  const reload = document.createElement("button");
  reload.textContent = "Reload";
  reload.addEventListener("click", () => location.reload());
  banner.append(reload);
  document.body.prepend(banner);
}
// end-snippet

const pages: readonly (readonly [string, string])[] = [
  ["/", "Queries"],
  ["/paging.html", "Paging"],
  ["/keyset.html", "Keyset"],
  ["/permissions.html", "Cached policy"],
  ["/live.html", "Live"],
  ["/commands.html", "Commands"]
];

// The links to every page, the one showing marked.
function navigation(): void {
  const nav = document.createElement("nav");
  nav.setAttribute("aria-label", "Samples");
  for (const [href, text] of pages) {
    const link = document.createElement("a");
    link.href = href;
    link.textContent = text;
    if (href === location.pathname ||
        (href === "/" && location.pathname === "/index.html")) {
      link.setAttribute("aria-current", "page");
    }

    nav.append(link);
  }

  document.querySelector("main")!.prepend(nav);
}

navigation();

export function fill(table: string, rows: readonly (readonly string[])[]): void {
  document.querySelector(`#${table} tbody`)!.replaceChildren(...rows.map(cells => {
    const row = document.createElement("tr");
    row.append(...cells.map(cell));
    return row;
  }));
}

export function cell(text: string): HTMLTableCellElement {
  const element = document.createElement("td");
  element.textContent = text;
  return element;
}

export function button(text: string, click: () => void, disabled = false): HTMLButtonElement {
  const element = document.createElement("button");
  element.textContent = text;
  element.disabled = disabled;
  element.addEventListener("click", click);
  return element;
}

export function status(text: string): void {
  document.getElementById("status")!.textContent = text;
}

export function messageOf(error: unknown): string {
  if (error instanceof Error) {
    return error.message;
  }

  return String(error);
}

// The sample's own endpoints beside Scry's, which a page posts to with nothing in the body.
export async function post(url: string): Promise<void> {
  const response = await fetch(url, { method: "POST" });
  if (!response.ok) {
    throw new Error(`${url} answered ${response.status}.`);
  }
}
